"""Embedded scoring sounds as base64 WAV constants (stdlib-only).

These are the two notification sounds the box plays on a score change
(agent/notify.py), vendored so the zipapp needs no data-file loading:

    GAIN_WAV_B64     pleasant chime  -- total score went UP
    PENALTY_WAV_B64  alarm klaxon    -- total score went DOWN (penalty)

Both are 16-bit mono PCM (gain 22050 Hz, penalty 11025 Hz); they are
decoded and written to a temp file at play time.

Provenance: ripped copies of the official CyberPatriot scoring-engine
notification sounds, obtained from the community "CyberPatriot
Soundboard" (github.com/ErikBoesen/cpsoundboard, gh-pages branch,
sounds/gain.wav + sounds/alarm.wav; captured 2026-09-09, then
resampled to 16-bit mono with ffmpeg). The repo's MIT license covers
its own code, not these sounds -- they belong to the CyberPatriot
program and are included here solely for training-environment parity.
See sounds.CREDIT.md next to this module.
"""

import base64


def wave_bytes(kind: str) -> bytes:
    """Return the WAV bytes for 'gain' or 'penalty'."""
    b64 = GAIN_WAV_B64 if kind == "gain" else PENALTY_WAV_B64
    return base64.b64decode(b64)


